function fixture({outboundEnabled=true,validSignature=true,emailClock=null,mailAccepted=true,callbackSaved=true,dispatchError=null}={}){const routes=new Map(),records=new Map(),counts={calls:0,recordings:0,stops:0,callbacks:0},crypto=require('node:crypto');const app={get:(path,...handlers)=>routes.set('GET '+path,handlers.at(-1)),post:(path,...handlers)=>routes.set('POST '+path,handlers.at(-1))};const pool={query:async(sql,args=[])=>{if(sql.startsWith('create table'))return {rows:[]};if(sql.startsWith('insert into daisy_manager_calls')){if(records.has(args[0]))return {rows:[]};records.set(args[0],{action_id:args[0],stream_token:args[1],payload:JSON.parse(args[2]),status:'claiming',result:{},transcript:[],updated_at:new Date()});return {rows:[{action_id:args[0]}]};}if(sql.startsWith('select *'))return {rows:records.has(args[0])?[records.get(args[0])]:[]};if(sql.includes('transcript=transcript')){const row=records.get(args[0]);if(!row.transcript.some(x=>x.event_id===args[2]))row.transcript.push(...JSON.parse(args[1]));return {rows:[]};}if(sql.startsWith('update daisy_manager_calls set call_sid=$2,status=case')){const row=records.get(args[0]);row.call_sid=args[1];if(row.status==='claiming')row.status=args[2];return {rows:[]};}if(sql.startsWith('update daisy_manager_calls set crm_synced_at='))return {rows:[]};if(sql.startsWith('update daisy_manager_calls set ')){const row=records.get(args[0]),parts=sql.slice(sql.indexOf(' set ')+5,sql.indexOf(',updated_at')).split(',');parts.forEach((part,i)=>{const key=part.split('=')[0];if(key==='result')Object.assign(row.result,JSON.parse(args[i+1]));else row[key]=args[i+1];});row.updated_at=new Date();return {rows:[]};}throw Error('Unhandled mock query: '+sql);}};
const calls=sid=>{const recordings=recordingSid=>({update:async()=>{counts.stops++;return {sid:recordingSid};}});recordings.create=async()=>{counts.recordings++;return {sid:'RE'+'a'.repeat(32)};};return {fetch:async()=>({sid,status:[...records.values()].find(r=>r.call_sid===sid)?.status||'in-progress'}),update:async input=>{counts.hangups=(counts.hangups||0)+1;return {sid,status:input.status};},recordings};};calls.create=async input=>{assert.equal(input.record,undefined);counts.lastDial=input.to;counts.calls++;if(dispatchError)throw dispatchError;return {sid:'CA'+'a'.repeat(32),status:'queued'};};const context={module:{exports:{}},require:name=>name==='twilio'?{validateRequest:()=>validSignature,twiml:{VoiceResponse:class{connect(){return {stream(){return {parameter(){}}}}}toString(){return '<Response/>'}}}}:name==='ws'?Object.assign(FakeSocket,{WebSocketServer:FakeServer}):name==='./test-room'?{registerTestRoom:()=>({handleUpgrade:()=>false})}:require(name),process:{env:{}},console,Buffer,URL,setTimeout:(fn,ms)=>{if(emailClock&&(ms===5000||ms===1500)){const timer={fn,ms,cancelled:false};emailClock.push(timer);return timer;}return setTimeout(fn,ms);},clearTimeout:timer=>{if(emailClock?.includes(timer))timer.cancelled=true;else clearTimeout(timer);},setInterval,clearInterval,AbortSignal,fetch:async(url,options)=>{counts.callbacks++;counts.lastFetch={url,body:JSON.parse(options.body)};if(counts.lastFetch.body.action==='schedule_callback'){counts.schedules=(counts.schedules||0)+1;return {ok:callbackSaved,status:callbackSaved?200:503,json:async()=>({scheduled:callbackSaved,callback:{id:'callback-job-test',due_at:counts.lastFetch.body.callback_at}})};}if(url.endsWith('/prephub-intake')){counts.emails=(counts.emails||0)+1;return {ok:mailAccepted,status:mailAccepted?200:503,json:async()=>({provider_accepted:mailAccepted})};}return {ok:true,status:200,json:async()=>({page_status:'live',current_page:{tab:'income'},preparation_areas:['Credit'],recommended_tab:'credit'})};}};vm.runInNewContext(fs.readFileSync(__dirname+'/manager-calls.js','utf8'),context);const api=context.module.exports,service=api.registerManagerCalls({app,pool,authenticateHelux(){},twilioClient:{calls},publicBaseUrl:'https://caller.example',authToken:'test',accountSid:'test',fromNumber:'+15555550100',heluxKey:'test',openaiKey:'test',outboundEnabled});const payload={action_id:'11111111-1111-4111-8111-111111111111',lead_id:'DPA-test',phone:'5555550101',first_name:'Test',permission_verified:true,callback_url:'https://fklchtsxahepzfzgcqdp.supabase.co/functions/v1/manager-daisy-call-result',preparation_context:{intake:{estimated_dpa:35000}},script:{objective:'Offer help choosing a PrepHub next step',opening:'I am Daisy, the AI assistant.',key_points:['Explain PrepHub'],recording_requested:true}};
const response=()=>({statusCode:200,body:null,status(code){this.statusCode=code;return this},json(body){this.body=body;return this},sendStatus(code){this.statusCode=code;return this},type(){return this},send(body){this.body=body;return this}});return {routes,records,counts,payload,response,api,service};}
test('approved dynamic brief dispatches once, uses existing phone service, and never pre-records',async()=>{const f=fixture(),handler=f.routes.get('POST /api/v1/manager/calls');let r=f.response();await handler({body:f.payload},r);assert.equal(r.statusCode,200);assert.equal(f.counts.calls,1);r=f.response();await handler({body:f.payload},r);assert.equal(r.body.duplicate,true);assert.equal(f.counts.calls,1);assert.equal(f.counts.recordings,0);assert.match(f.api.callInstructions(f.payload),/Never invent offers/);});
test('disabled outbound and missing permission cannot dial',async()=>{const f=fixture({outboundEnabled:false}),r=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},r);assert.equal(r.statusCode,409);assert.equal(f.counts.calls,0);const g=fixture(),res=g.response();await g.routes.get('POST /api/v1/manager/calls')({body:{...g.payload,permission_verified:false}},res);assert.equal(res.statusCode,422);assert.equal(g.counts.calls,0);});
test('unsigned provider callback cannot change call state',async()=>{const f=fixture({validSignature:false});await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},f.response());const c=f.records.get(f.payload.action_id),r=f.response();await f.routes.get('POST /api/v1/manager/status')({query:{action_id:c.action_id,token:c.stream_token},body:{CallSid:c.call_sid,CallStatus:'completed'},get:()=>''},r);assert.equal(r.statusCode,403);assert.equal(c.status,'queued');});
test('new media route is isolated and requires the per-call token before connecting AI',async()=>{const f=fixture();assert.equal(f.service.handleUpgrade({url:'/api/v1/twilio/media'},null,null),false);const socket=new FakeSocket();assert.equal(f.service.handleUpgrade({url:'/api/v1/manager/media'},socket,null),true);const before=FakeSocket.instances.length;await socket.emitAsync('message',JSON.stringify({event:'start',start:{customParameters:{action_id:f.payload.action_id,token:'wrong'},callSid:'CA'+'a'.repeat(32)}}));assert.equal(socket.readyState,3);assert.equal(FakeSocket.instances.length,before);});
async function liveSession(f){await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},f.response());const c=f.records.get(f.payload.action_id),socket=new FakeSocket();f.service.handleUpgrade({url:'/api/v1/manager/media'},socket,null);await socket.emitAsync('message',JSON.stringify({event:'start',start:{customParameters:{action_id:c.action_id,token:c.stream_token},callSid:c.call_sid,streamSid:'MZ-test'}}));const ai=FakeSocket.instances.at(-1);await ai.emitAsync('open');return {c,socket,ai};}
const event=(socket,data)=>socket.emitAsync('message',JSON.stringify(data));
async function noticePlayed(f,session){await event(session.ai,{type:'response.created'});await event(session.ai,{type:'response.output_audio_transcript.done',item_id:'notice-1',transcript:f.api.RECORDING_NOTICE+' Is now a good time?'});await event(session.ai,{type:'response.done'});await event(session.socket,{event:'mark',mark:{name:'manager-recording-notice'}});}
test('recording starts after played notice and affirmative continuation, without a separate permission question',async()=>{const f=fixture(),session=await liveSession(f),{ai,c,socket}=session;assert.equal(ai.sent[0].session.audio.output.voice,'marin');await event(ai,{type:'response.function_call_arguments.done',name:'recording_consent',call_id:'early',arguments:'{"consent":true}'});assert.equal(f.counts.recordings,0);await noticePlayed(f,session);assert.equal(f.counts.recordings,0);await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'yes-1',transcript:'Yes, now is fine.'});assert.equal(f.counts.recordings,1);assert.equal(c.result.recording_consent_source,'notice_and_affirmative_continuation');assert.ok(c.result.recording_notice_delivered_at);await event(ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'finish',arguments:JSON.stringify({outcome:'interested',summary:'Requested help choosing next step',next_action:'Owner to follow up'})});assert.equal(c.result.outcome,'interested');assert.ok(c.transcript.some(t=>t.text==='Yes, now is fine.'));socket.close();});
test('silence, unclear replies, and objections do not start a recording',async()=>{const f=fixture(),session=await liveSession(f);await noticePlayed(f,session);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'unclear',transcript:'It is seventeen.'});assert.equal(f.counts.recordings,0);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'no',transcript:"I do not want to be recorded."});assert.equal(f.counts.recordings,0);assert.equal(session.c.result.recording_declined,true);session.socket.close();});
test('an interrupted recording notice does not authorize recording',async()=>{const f=fixture(),session=await liveSession(f);await event(session.ai,{type:'response.created'});await event(session.ai,{type:'input_audio_buffer.speech_started'});await event(session.ai,{type:'response.output_audio_transcript.done',transcript:f.api.RECORDING_NOTICE});await event(session.ai,{type:'response.done'});await event(session.socket,{event:'mark',mark:{name:'manager-recording-notice'}});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'yes',transcript:'Yes.'});assert.equal(f.counts.recordings,0);session.socket.close();});
test('a later objection stops an existing recording',async()=>{const f=fixture(),session=await liveSession(f);await noticePlayed(f,session);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'yes',transcript:'No problem, go ahead.'});assert.equal(f.counts.recordings,1);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'stop',transcript:'Please stop recording.'});assert.equal(f.counts.stops,1);assert.ok(session.c.result.recording_withdrawn_at);session.socket.close();});
test('the standard opening identifies Daisy and company without a forced AI announcement',()=>{const f=fixture(),instructions=f.api.callInstructions(f.payload);assert.ok(!instructions.includes('identify yourself as an AI assistant'));assert.ok(!instructions.includes('Explain that you are an AI assistant'));assert.match(instructions,/answer truthfully/);assert.match(instructions,/Do not ask a separate recording-permission question/);});

test('explicit owner-authorized manager call dispatches without fabricating customer verification',async()=>{const f=fixture();delete f.payload.permission_verified;f.payload.owner_authorized=true;const r=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},r);assert.equal(r.statusCode,200);assert.equal(f.counts.calls,1);});

test('Exact script mode excludes removed legacy wording from caller instructions',()=>{const f=fixture();f.payload.script={...f.payload.script,script_text:'Hello Test. When can you finish filing?',opening:'LEGACY UNWANTED OPENING',key_points:['REMOVED OFFER'],questions:['UNWANTED QUESTION']};const instructions=f.api.callInstructions(f.payload);assert.match(instructions,/EXACT SCRIPT MODE/);assert.match(instructions,/Hello Test. When can you finish filing/);assert.ok(!instructions.includes('LEGACY UNWANTED OPENING')&&!instructions.includes('REMOVED OFFER')&&!instructions.includes('UNWANTED QUESTION'));assert.match(instructions,/verbatim/);});

test('Caller uses the dispatched settings snapshot for greeting, delivery and recording text',()=>{const f=fixture();f.payload.script.script_text='Approved dialogue only.';f.payload.caller_settings={version:7,settings:{assistant_name:'Daisy',company_name:'Example Homebuyer Team',introduce_as_ai:true,recording_mode:'notice_and_continue',recording_notice:'This call may be recorded for training.',availability_question:'Can we talk briefly?',script_delivery:'guided',custom_guidance:'Keep replies concise.'}};const words=f.api.callInstructions(f.payload);assert.match(words,/Example Homebuyer Team/);assert.match(words,/Identify yourself as a digital assistant/);assert.match(words,/two-to-three-minute orientation choice/);assert.match(words,/GUIDED SCRIPT MODE/);assert.match(words,/Keep replies concise/);assert.match(words,/This call may be recorded for training/);assert.ok(!words.includes('EXACT SCRIPT MODE'));});
test('Global recording-off settings prevent recording even when the script requested it',async()=>{const f=fixture();f.payload.caller_settings={version:2,settings:{recording_mode:'off'}};const session=await liveSession(f);await noticePlayed(f,session);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'yes',transcript:'Yes, go ahead.'});await event(session.ai,{type:'response.function_call_arguments.done',name:'recording_consent',call_id:'tool',arguments:'{"consent":true}'});assert.equal(f.counts.recordings,0);session.socket.close();});
test('Malformed caller configuration cannot dispatch a phone call',async()=>{const f=fixture();f.payload.caller_settings={version:1,settings:{recording_mode:'secret'}};const res=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},res);assert.equal(res.statusCode,422);assert.equal(f.counts.calls,0)});
test('Custom notices and explicit-permission mode use their own played-message evidence',async()=>{const f=fixture();f.payload.caller_settings={version:3,settings:{recording_mode:'ask_permission',recording_notice:'This call may be recorded for training.'}};const session=await liveSession(f),message=f.api.recordingMessage(f.payload);assert.match(message,/May I record this call/);await event(session.ai,{type:'response.created'});await event(session.ai,{type:'response.output_audio_transcript.done',transcript:message});await event(session.ai,{type:'response.done'});await event(session.socket,{event:'mark',mark:{name:'manager-recording-notice'}});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'yes',transcript:'Yes.'});assert.equal(f.counts.recordings,1);assert.equal(session.c.result.caller_settings_version,3);session.socket.close();});

test('A two-area call cannot close normally after discussing taxes alone',async()=>{const f=fixture();f.payload.script.script_text='Which years have you filed?\n\nHave your monthly payments changed?';f.payload.preparation_sections=[{area:'Taxes',script_id:'tax',version:1,text:'Which years have you filed?'},{area:'DTI',script_id:'dti',version:2,text:'Have your monthly payments changed?'}];const session=await liveSession(f);await event(session.ai,{type:'response.output_audio_transcript.done',item_id:'tax-question',transcript:'Which years have you filed?'});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'tax-answer',transcript:'I filed 2025.'});await event(session.ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'too-early',arguments:JSON.stringify({outcome:'completed',summary:'Taxes discussed',next_action:'Check later'})});assert.equal(session.c.result.outcome,undefined);const output=session.ai.sent.filter(e=>e.item?.type==='function_call_output').at(-1);assert.match(output.item.output,/DTI/);assert.match(output.item.output,/Have your monthly payments changed/);await event(session.ai,{type:'response.output_audio_transcript.done',item_id:'dti-question',transcript:'Have your monthly payments changed?'});await event(session.ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'complete',arguments:JSON.stringify({outcome:'completed',summary:'Both discussed',next_action:'Review actual answers'})});assert.equal(session.c.result.outcome,'completed');assert.equal(session.c.result.preparation_coverage.length,2);session.socket.close();});
test('An evidenced request to end is respected while the second area remains deferred',async()=>{const f=fixture();f.payload.script.script_text='Have your payments changed?';f.payload.preparation_sections=[{area:'DTI',text:'Have your payments changed?'}];const session=await liveSession(f);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'exit',transcript:'I have to go, call me back tomorrow.'});await event(session.ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'exit-call',arguments:JSON.stringify({outcome:'callback',summary:'Client asked to stop for now',next_action:'Requested callback',client_exit_quote:'I have to go'})});assert.equal(session.c.result.outcome,'callback');assert.equal(session.c.result.preparation_deferred[0],'DTI');session.socket.close();});
test('Unsubstantiated exit quotes and callback dates alone do not bypass remaining areas',()=>{const f=fixture();assert.equal(f.api.earlyExitEvidence({outcome:'callback',client_exit_quote:'I have to go'},[{role:'client',text:'Next month works for the tax check-in.'}]),false);assert.equal(f.api.earlyExitEvidence({outcome:'callback',client_exit_quote:'Next month'},[{role:'client',text:'Next month works.'}]),false);});

test('Conversational mode accepts paraphrased discussion supported by client quotes, not exact question recital',async()=>{const f=fixture();f.payload.caller_settings={version:3,settings:{script_delivery:'guided',voice:'coral'}};f.payload.script.script_text='Which years have you filed?\n\nHave your monthly payments changed?';f.payload.preparation_sections=[{area:'Taxes',text:'Which years have you filed?'},{area:'DTI',text:'Have your monthly payments changed?'}];const session=await liveSession(f);assert.equal(session.ai.sent[0].session.audio.output.voice,'coral');assert.equal(session.ai.sent[0].session.audio.input.turn_detection.silence_duration_ms,600);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'tax',transcript:'2024 is still outstanding.'});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'dti',transcript:'My monthly payments have not changed.'});await event(session.ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'guided-end',arguments:JSON.stringify({outcome:'completed',summary:'Discussed both areas',next_action:'Review filing progress',preparation_area_outcomes:[{area:'Taxes',disposition:'discussed',client_quote:'2024 is still outstanding.',next_step:'Filing status review'},{area:'DTI',disposition:'discussed',client_quote:'My monthly payments have not changed.',next_step:'Review working numbers'}]})});assert.equal(session.c.result.outcome,'completed');assert.equal(session.c.result.preparation_coverage.every(x=>x.discussion_evidenced),true);session.socket.close();});
test('Conversational coverage rejects invented client evidence and does not label unknown areas discussed',()=>{const f=fixture();f.payload.caller_settings={version:3,settings:{script_delivery:'guided'}};f.payload.preparation_sections=[{area:'Taxes',text:'Which years?'}];const coverage=f.api.preparationCoverage(f.payload,[{role:'client',text:'Hello.'}],[{area:'Taxes',disposition:'discussed',client_quote:'I filed everything.'}]);assert.equal(coverage[0].coverage_addressed,false);});
test('Objective mode allows relevant follow-up questions while preserving truthful action limits',()=>{const f=fixture();f.payload.caller_settings={version:3,settings:{script_delivery:'guided'}};f.payload.script.script_text='Approved preparation playbook';f.payload.preparation_context={intake:{focus_areas:['taxes']}};const instructions=f.api.callInstructions(f.payload);assert.match(instructions,/OBJECTIVE-BASED CONVERSATION/);assert.match(instructions,/necessary follow-up questions/);assert.match(instructions,/cannot directly book appointments/);assert.match(instructions,/unverified CRM data/);});

test('Assistance confirmation pauses before email, needs and orientation',()=>{const f=fixture();let t=f.api.nextGuidedTurn('identity','This is Test speaking.',f.payload);assert.equal(t.stage,'amount');assert.match(t.instructions,/\$35,000/);assert.match(t.instructions,/is that correct/);for(const expected of ['email','needs','orientation','login','login_confirm','preparation']){t=f.api.nextGuidedTurn(t.stage,'Yes.',f.payload);assert.equal(t.stage,expected);}assert.match(t.instructions,/get_prephub_status/);});
