test('Guided caller disables automatic silence replies and requests one bounded response per client reply',async()=>{const f=fixture();f.payload.caller_settings={version:5,settings:{script_delivery:'guided',voice:'marin'}};const session=await liveSession(f);assert.equal(session.ai.sent[0].session.audio.input.turn_detection.create_response,false);assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,0);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'identity',transcript:'This is Test speaking.'});const request=session.ai.sent.find(e=>e.type==='response.create');assert.match(request.response.instructions,/ONE question/);assert.match(request.response.instructions,/first-time homebuyer request for assistance/);session.socket.close();});
test('Walkthrough uses actual PrepHub controls and states live-screen access limitations',()=>{const f=fixture();assert.match(f.api.PREPHUB_WALKTHROUGH,/Income & DTI/);assert.match(f.api.PREPHUB_WALKTHROUGH,/Save My Numbers/);assert.match(f.api.PREPHUB_WALKTHROUGH,/does not show screen pixels or unsaved entries/);});
test('A normal negative answer after recording starts does not withdraw recording agreement',async()=>{const f=fixture(),session=await liveSession(f);await noticePlayed(f,session);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'agree-record',transcript:'Yes, now is fine.'});assert.equal(f.counts.recordings,1);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'no-email',transcript:'No, I have not checked my email yet.'});assert.equal(f.counts.stops,0);assert.equal(session.c.result.recording_declined,undefined);session.socket.close();});

test('Unclear availability never becomes consent or a claimed recording failure',async()=>{const f=fixture();f.payload.caller_settings={version:6,settings:{script_delivery:'guided',voice:'marin'}};const session=await liveSession(f);await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done'});await noticePlayed(f,session);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'unclear-new',transcript:'I see you.'});assert.equal(f.counts.recordings,0);const turn=f.api.nextGuidedTurn('orientation','I see you.',f.payload);assert.equal(turn.stage,'orientation');assert.match(turn.instructions,/Do not assume which option/);await event(session.ai,{type:'response.function_call_arguments.done',name:'recording_consent',call_id:'pending',arguments:'{"consent":true}'});const output=JSON.parse(session.ai.sent.filter(e=>e.item?.type==='function_call_output').at(-1).item.output);assert.equal(output.recording_started,false);assert.equal(output.conversation_may_continue,true);assert.equal(output.status,'awaiting_notice_and_clear_continuation');assert.match(f.api.callInstructions(f.payload),/RECORDING IS OPTIONAL, NOT A CONVERSATION GATE/);session.socket.close();});
test('A different stated name requires clarification before personal details',()=>{const f=fixture();const identity=f.api.nextGuidedTurn('identity','This is Doug speaking.',f.payload);assert.equal(identity.stage,'identity');assert.match(identity.instructions,/different first name/);assert.match(identity.instructions,/Do not share financial/);});

test('A tool completion queued before the greeting transcript cannot answer Daisy’s own question',async()=>{const f=fixture();f.payload.script.script_text='Preparation playbook.';f.payload.caller_settings={version:6,settings:{script_delivery:'guided'}};const {ai,socket}=await liveSession(f);await event(ai,{type:'session.updated'});const count=()=>ai.sent.filter(e=>e.type==='response.create').length;assert.equal(count(),1);await event(ai,{type:'response.function_call_arguments.done',name:'recording_consent',call_id:'early-tool',arguments:'{"consent":true}'});await event(ai,{type:'response.output_audio_transcript.done',item_id:'greet',transcript:'Hi, is Test available?'});await event(ai,{type:'response.done'});assert.equal(count(),1);await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'blank',transcript:'  '});assert.equal(count(),1);await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'real',transcript:'This is Test speaking.'});assert.equal(count(),2);socket.close();});
test('No-client tool attempts cannot invent a callback outcome or close the conversation',async()=>{const f=fixture();f.payload.caller_settings={version:6,settings:{script_delivery:'guided'}};const {ai,socket,c}=await liveSession(f);await event(ai,{type:'session.updated'});await event(ai,{type:'response.output_audio_transcript.done',item_id:'opening',transcript:'Hi, is Test available?'});await event(ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'imagined-callback',arguments:JSON.stringify({outcome:'callback',summary:'Client wants callback',next_action:'Call back'})});await event(ai,{type:'response.done'});assert.equal(c.result.outcome,undefined);assert.equal(ai.sent.filter(e=>e.type==='response.create').length,1);socket.close();});

test('Opening identifies submitted form and does not offer record edits',()=>{const f=fixture(),a=f.api.nextGuidedTurn('identity','This is Ted speaking.',f.payload);assert.match(a.instructions,/Am I speaking with Test/);assert.match(a.instructions,/Do not offer the caller a choice to edit/);assert.match(f.api.nextGuidedTurn('identity','Yes, speaking.',f.payload).instructions,/first-time homebuyer request for assistance/);assert.match(f.api.nextGuidedTurn('orientation','For what?',f.payload).instructions,/Clarify whether/);});
test('missing assistance amount uses Doug’s potential-assistance introduction without claiming a recorded request',()=>{const f=fixture();delete f.payload.preparation_context.intake.estimated_dpa;const words=f.api.simpleLine('amount',f.payload);assert.match(words,/Doug told me to give you a call/);assert.match(words,/may be interested in up to \$35,000/);assert.ok(!words.includes('?'));assert.doesNotMatch(words,/you requested|you were looking|your first-time homebuyer request|approved|awarded/);assert.equal(f.api.nextGuidedTurn('amount','Yes.',f.payload).stage,'email');});

test('live page tool is scoped to immutable approved recipient and rejects transcript-selected recipients',async()=>{
 const f=fixture();f.payload.lead_id='DPA-test-authorized';f.payload.caller_settings={version:6,settings:{script_delivery:'guided',voice:'marin'}};
 const session=await liveSession(f);const tool=async(id,args)=>{await event(session.ai,{type:'response.function_call_arguments.done',name:'get_prephub_status',call_id:id,arguments:JSON.stringify(args)});return JSON.parse(session.ai.sent.filter(e=>e.item?.type==='function_call_output').at(-1).item.output);};
 assert.equal((await tool('before-identity',{})).ok,false);
 for(const [i,transcript] of ['This is Test speaking.','Yes.','Yes, I have the email.','Yes, that makes sense.','Yes.','Yes.','Yes.'].entries()){
 await event(session.ai,{type:'response.done'});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'nav-'+i,transcript});
 }
 assert.equal((await tool('read-page',{})).ok,true);assert.equal(f.counts.lastFetch.body.lead_id,'DPA-test-authorized');
 assert.equal((await tool('injected-recipient',{lead_id:'DPA-other-person'})).ok,false);
 session.c.payload.preparation_sections=[{area:'Income',text:'Do you work?'},{area:'Credit',text:'Review your credit report?'}];
 await event(session.ai,{type:'response.function_call_arguments.done',name:'finish_call',call_id:'nav-finish',arguments:JSON.stringify({outcome:'completed',summary:'Credit next step discussed',next_action:'Review saved report',preparation_area_outcomes:[{area:'Credit',disposition:'discussed',client_quote:'Yes, I have the email.',next_step:'Review report'}]})});
 assert.equal(session.c.result.outcome,'completed');assert.equal(session.c.result.preparation_coverage.length,1);assert.equal(session.c.result.preparation_coverage[0].area,'Credit');
 session.socket.close();
});

test('All documented needs are mentioned without inventing tax years',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['credit','taxes','dti'],credit_score:639,household_income:65000,tax_return_history:'filed_1_year'}};const words=f.api.preparationSummary(f.payload);assert.match(words,/639/);assert.match(words,/65,000/);assert.match(words,/one year of filed tax returns/);assert.ok(!words.includes('haven’t filed taxes for two years'));});
test('Saved script block edits supply exact current phase wording',()=>{const f=fixture();f.payload.script.script_text='[PrepHub:email]\nMy edited login question?\n[PrepHub:end]';assert.equal(f.api.simpleLine('email',f.payload),'My edited login question?');assert.ok(f.api.nextGuidedTurn('amount','Yes.',f.payload).instructions.includes('My edited login question?'));});
test('A login-first call leaves other area work pending instead of forcing an interview',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['credit','taxes'],credit_score:620}};const turn=f.api.nextGuidedTurn('preparation','Yes.',f.payload);assert.match(turn.instructions,/leave their work for a later preparation session/);assert.match(turn.instructions,/Gather My Three Credit Reports/);});

test('Reassurance uses the customer name and removes I understand',()=>{const f=fixture();f.payload.preparation_context={intake:{estimated_dpa:35000,focus_areas:['credit','taxes'],credit_score:639}};let t=f.api.nextGuidedTurn('amount','Yes.',f.payload);assert.equal(t.stage,'email');t=f.api.nextGuidedTurn(t.stage,'Yes, I see it.',f.payload);assert.equal(t.stage,'needs');assert.match(t.instructions,/Based on your form, Test,/);assert.match(t.instructions,/639/);t=f.api.nextGuidedTurn(t.stage,'I am frustrated and have questions.',f.payload);assert.equal(t.stage,'orientation');assert.match(t.instructions,/Let the client finish/);assert.match(t.instructions,/But there’s no need to worry, Test/);assert.ok(!t.instructions.includes('I understand'));assert.match(t.instructions,/two to three minutes/);});
test('Orientation sends explicit callback choice to callback branch, unclear choice waits',()=>{const f=fixture();assert.equal(f.api.nextGuidedTurn('orientation','I would prefer a callback.',f.payload).stage,'callback_time');assert.equal(f.api.nextGuidedTurn('orientation','What resources?',f.payload).stage,'orientation');assert.equal(f.api.nextGuidedTurn('orientation','Yes, I have time now.',f.payload).stage,'login');});

test('terminal-call reconciliation computes coverage outside socket state',async()=>{const f=fixture();f.payload.script.script_text='Did you review your credit report?';f.payload.preparation_sections=[{area:'Credit',text:f.payload.script.script_text}];await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},f.response());const c=f.records.get(f.payload.action_id);c.status='completed';c.transcript=[{role:'daisy',text:f.payload.script.script_text},{role:'client',text:'Yes.'}];c.result.outcome='completed';const r=f.response();await f.routes.get('GET /api/v1/manager/calls/:id')({params:{id:c.action_id}},r);assert.equal(c.result.preparation_coverage[0].area,'Credit');});

test('client identity reply arriving before the greeting finishes is not discarded',async()=>{const f=fixture();f.payload.caller_settings={version:8,settings:{script_delivery:'guided',voice:'marin'}};const {ai,socket}=await liveSession(f);await event(ai,{type:'session.updated'});await event(ai,{type:'response.created'});await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'early-name',transcript:'This is Test speaking.'});await event(ai,{type:'response.output_audio_transcript.done',item_id:'late-greeting',transcript:'Hi, is Test available?'});await event(ai,{type:'response.done',response:{status:'completed'}});const requests=ai.sent.filter(e=>e.type==='response.create');assert.equal(requests.length,2);assert.match(requests[1].response.instructions,/Excellent, I’m Daisy/);socket.close();});

test('a standalone thank-you after identity continues the same script once without another client prompt',async()=>{const f=fixture();f.payload.first_name='Tess';f.payload.caller_settings={version:8,settings:{script_delivery:'guided',voice:'marin'}};const {ai,socket}=await liveSession(f);await event(ai,{type:'session.updated'});await event(ai,{type:'response.done',response:{status:'completed'}});await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'tess-confirmed',transcript:'This is Tess speaking.'});let request=ai.sent.filter(e=>e.type==='response.create').at(-1);assert.match(request.response.instructions,/Excellent, I’m Daisy/);assert.equal(request.response.tool_choice,'none');await event(ai,{type:'response.output_audio_transcript.done',item_id:'ack-only',transcript:'Thank you.'});const before=ai.sent.filter(e=>e.type==='response.create').length;await event(ai,{type:'response.done',response:{status:'completed'}});assert.equal(ai.sent.filter(e=>e.type==='response.create').length,before+1);request=ai.sent.filter(e=>e.type==='response.create').at(-1);assert.match(request.response.instructions,/Excellent, I’m Daisy/);await event(ai,{type:'response.output_audio_transcript.done',item_id:'ack-again',transcript:'Thank you.'});await event(ai,{type:'response.done',response:{status:'completed'}});assert.equal(ai.sent.filter(e=>e.type==='response.create').length,before+1);socket.close();});
test('a completed question does not automatically advance or trigger acknowledgment recovery',async()=>{const f=fixture();f.payload.caller_settings={version:8,settings:{script_delivery:'guided'}};const {ai,socket}=await liveSession(f);await event(ai,{type:'session.updated'});await event(ai,{type:'response.done',response:{status:'completed'}});await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'identity-normal',transcript:'This is Test speaking.'});const before=ai.sent.filter(e=>e.type==='response.create').length;await event(ai,{type:'response.output_audio_transcript.done',item_id:'actual-script',transcript:'Excellent, I’m Daisy. Does that make sense?'});await event(ai,{type:'response.done',response:{status:'completed'}});assert.equal(ai.sent.filter(e=>e.type==='response.create').length,before);socket.close();});

test('recording-off has no spoken notice in the prompt or identity transition',async()=>{const f=fixture();f.payload.caller_settings={version:9,settings:{script_delivery:'guided',recording_mode:'off'}};f.payload.script.recording_requested=false;const instructions=f.api.callInstructions(f.payload);assert.match(instructions,/Customer-call recording is OFF/);assert.ok(!instructions.includes('This call may be recorded'));const t=f.api.nextGuidedTurn('identity','This is Test speaking.',f.payload);assert.equal(t.stage,'amount');assert.ok(!t.instructions.includes('configured recording notice'));const {ai,socket}=await liveSession(f);await event(ai,{type:'session.updated'});await event(ai,{type:'response.done'});await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'off-identity',transcript:'This is Test speaking.'});assert.ok(!ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions.includes('This call may be recorded'));assert.equal(f.counts.recordings,0);socket.close();});

test('owner rehearsal keeps captured recording and suppresses only the rehearsal spoken notice',()=>{const f=fixture();f.payload.caller_settings={version:8,settings:{script_delivery:'guided',recording_mode:'notice_and_continue'}};f.payload.rehearsal_recording=true;const instructions=f.api.callInstructions(f.payload);assert.match(instructions,/rehearsal records both sides/);assert.ok(!instructions.includes('This call may be recorded'));assert.ok(!f.api.nextGuidedTurn('identity','This is Test speaking.',f.payload).instructions.includes('configured recording notice'));assert.equal(f.api.validRequest(f.payload),false);delete f.payload.rehearsal_recording;assert.match(f.api.callInstructions(f.payload),/This call may be recorded/);assert.equal(f.api.validRequest(f.payload),true);});

test('wrong assistance goal branches to correction and preserves reported-versus-awarded distinction',()=>{const f=fixture();let t=f.api.nextGuidedTurn('amount','No.',f.payload);assert.equal(t.stage,'amount_correction');t=f.api.nextGuidedTurn(t.stage,'I was looking for $20,000.',f.payload);assert.equal(t.stage,'email');assert.match(t.instructions,/client-reported goal/);assert.match(t.instructions,/do not claim to have changed/);});

test('Preparation reasons connect income to debts and housing without declaring income insufficient',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['income','dti'],household_income:68000}};const words=f.api.preparationSummary(f.payload);assert.equal((words.match(/68,000/g)||[]).length,1);assert.match(words,/need to analyze how much room/);assert.match(words,/monthly housing payment after accounting for your other debts/);assert.match(words,/important preparation step/);assert.doesNotMatch(words,/too low|insufficient|denied|qualify for/);});
test('Each documented preparation need includes a reason and retains the saved phase question',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['credit','dti','job','taxes'],credit_score:620,household_income:68000,employment_history:'in_and_out_of_work',tax_return_history:'filed_1_year'}};const words=f.api.simpleLine('needs',f.payload);for(const fragment of [/620/,/middle FICO of 640/,/some lenders may consider lower/,/68,000/,/other debts/,/time in and out of work/,/income stability/,/same employer/,/one year of filed tax returns/,/Some loans require two years/,/Does that make sense/])assert.match(words,fragment);assert.doesNotMatch(words,/2024|2025|three years|all lenders|flagged/);});
test('Continuous job changes are not described as employment gaps',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['job'],employment_history:'switched_jobs_continuous_2_years'}};const words=f.api.preparationSummary(f.payload);assert.match(words,/continuous employment/);assert.doesNotMatch(words,/in and out|gaps/);});
test('Completed preparation areas do not reappear in reason summary',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['credit','income','taxes'],credit_score:620,household_income:68000,tax_return_history:'not_sure'},saved_progress:{readiness:{assessed:{credit:true,income:true},sections:{credit:25,income:25}}}};const words=f.api.preparationSummary(f.payload);assert.match(words,/unsure about your tax/);assert.doesNotMatch(words,/620|68,000|middle FICO/);});
test('Missing intake values produce explanation without invented numbers or job history',()=>{const f=fixture();f.payload.preparation_context={intake:{focus_areas:['credit','dti','job','taxes']}};const words=f.api.preparationSummary(f.payload);assert.match(words,/credit preparation needs review/);assert.match(words,/monthly debts/);assert.match(words,/work history needs review/);assert.match(words,/tax-filing history needs review/);assert.doesNotMatch(words,/\$|reported|in and out|2024|2025/);});

test('Identity answers advance directly to the approved introduction including Tess transcription',()=>{const f=fixture();for(const answer of ['Yes.','Yes, this is Test speaking.','This is Tess speaking.','I just told you, this is Tess speaking, yes.','Speaking.']){const next=f.api.nextGuidedTurn('identity',answer,f.payload);assert.equal(next.stage,'amount',answer);assert.match(next.instructions,/Excellent, I’m Daisy/);assert.match(next.instructions,/Never say "confirmed"/);assert.doesNotMatch(next.instructions,/Am I speaking with/);}});
test('Identity questions, denial and unrelated names do not expose the introduction',()=>{const f=fixture();for(const answer of ['Who is this?','This is Doug speaking.','This is Ted speaking.','No, not me.','This is not Test.','Hello?','If I say yes','This is my wife.'])assert.equal(f.api.nextGuidedTurn('identity',answer,f.payload).stage,'identity',answer);});
test('Unexpected confirmed-only output recovers once into the approved introduction',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const {ai,socket}=await liveSession(f);await event(ai,{type:'session.updated'});await event(ai,{type:'response.done',response:{status:'completed'}});await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'tess-name',transcript:'This is Tess speaking.'});assert.match(ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/Excellent, I’m Daisy/);await event(ai,{type:'response.output_audio_transcript.done',item_id:'bad-ack',transcript:'Confirmed. Thank you, Test.'});const before=ai.sent.filter(e=>e.type==='response.create').length;await event(ai,{type:'response.done',response:{status:'completed'}});assert.equal(ai.sent.filter(e=>e.type==='response.create').length,before+1);assert.match(ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/Excellent, I’m Daisy/);socket.close();});

test('Broken recognition asks one exact clarification, then yes advances without filler',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const {ai,socket,c}=await liveSession(f);c.payload.rehearsal_recording=true;await event(ai,{type:'session.updated'});let req=ai.sent.filter(e=>e.type==='response.create').at(-1).response;assert.deepEqual(Array.from(req.input),[]);assert.match(req.instructions,/Hi, is Test available/);await event(ai,{type:'response.done',response:{status:'completed'}});for(const [id,words]of [['noise','neonit.'],['fragment','This is']]){await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:id,transcript:words});req=ai.sent.filter(e=>e.type==='response.create').at(-1).response;assert.deepEqual(Array.from(req.input),[]);assert.match(req.instructions,/Sorry, I didn’t catch that. Am I speaking with Test/);assert.doesNotMatch(req.instructions,/Excellent, I’m Daisy/);await event(ai,{type:'response.done',response:{status:'completed'}});}await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'yes-after-clarify',transcript:'Yes.'});req=ai.sent.filter(e=>e.type==='response.create').at(-1).response;assert.deepEqual(Array.from(req.input),[]);assert.match(req.instructions,/Excellent, I’m Daisy/);assert.match(req.instructions,/35,000/);assert.equal(req.tool_choice,'none');assert.doesNotMatch(req.instructions,/This call may be recorded/);socket.close();});
test('Actual preparation questions retain conversation context rather than becoming isolated speech',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const {ai,socket,c}=await liveSession(f);c.payload.rehearsal_recording=true;await event(ai,{type:'session.updated'});await event(ai,{type:'response.done',response:{status:'completed'}});for(const [id,words]of [['who','Yes'],['amount','Yes'],['email','Yes']]){await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:id,transcript:words});await event(ai,{type:'response.done',response:{status:'completed'}});}await event(ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'question',transcript:'Why do I need to review this?'});const req=ai.sent.filter(e=>e.type==='response.create').at(-1).response;assert.equal(req.input,undefined);assert.match(req.instructions,/Briefly address any actual question/);socket.close();});

test('Latest email confirmation variants proceed to preparation needs, never login',()=>{const f=fixture();for(const reply of ['Oh yeah, see, yeah.','Oh, yes.','Um, yeah.','I see it.','I got the email.','I do.']){const turn=f.api.nextGuidedTurn('email',reply,f.payload);assert.equal(turn.stage,'needs',reply);assert.equal(turn.scriptLine,f.api.simpleLine('needs',f.payload));assert.doesNotMatch(turn.scriptLine,/sign.in|log.?in/i);}for(const reply of ['No.','Oh no, I cannot find it.','Yes, but I cannot find the email.'])assert.equal(f.api.nextGuidedTurn('email',reply,f.payload).stage,'access_help');const unclear=f.api.nextGuidedTurn('email','hmm',f.payload);assert.equal(unclear.stage,'email');assert.equal(unclear.scriptLine,'Do you see the welcome email from PrepHub?');});
test('Full orientation is selected after needs acknowledgment before any login request',()=>{const f=fixture();let turn=f.api.nextGuidedTurn('identity','Yes',f.payload);assert.equal(turn.stage,'amount');turn=f.api.nextGuidedTurn(turn.stage,'Yes',f.payload);assert.equal(turn.stage,'email');turn=f.api.nextGuidedTurn(turn.stage,'Oh yeah, see, yeah.',f.payload);assert.equal(turn.stage,'needs');turn=f.api.nextGuidedTurn(turn.stage,'Yes, that makes sense.',f.payload);assert.equal(turn.stage,'orientation');assert.equal(turn.scriptLine,f.api.simpleLine('orientation',f.payload));assert.match(turn.scriptLine,/But there’s no need to worry/);assert.match(turn.scriptLine,/two to three minutes/);assert.doesNotMatch(turn.scriptLine,/sign.in|log.?in/i);assert.equal(f.api.nextGuidedTurn(turn.stage,'Yes.',f.payload).stage,'login');});
test('Client goodbye ends the call rather than resuming an explanation',()=>{const f=fixture();for(const words of ['All right, bye.','Goodbye.','Okay, bye.']){const turn=f.api.nextGuidedTurn('orientation',words,f.payload);assert.equal(turn.stage,'wrapup');assert.match(turn.instructions,/Do not explain more/);}});

test('Income below seventy thousand uses analysis wording without declaring unaffordability',()=>{const f=fixture();for(const income of [68000,69999,45000]){f.payload.preparation_context={intake:{focus_areas:['dti'],household_income:income}};const words=f.api.preparationSummary(f.payload);assert.match(words,/we need to analyze/);assert.match(words,/monthly housing payment after accounting for your other debts/);assert.doesNotMatch(words,/cannot afford|not enough|too low|denied/);}for(const income of [70000,90000]){f.payload.preparation_context={intake:{focus_areas:['dti'],household_income:income}};assert.doesNotMatch(f.api.preparationSummary(f.payload),/important preparation step before moving forward/);}});
test('Telephone audio filters noise before VAD while keeping real speech interruption and response timing',async()=>{const f=fixture(),{ai,socket}=await liveSession(f);const audio=ai.sent[0].session.audio;assert.equal(audio.input.noise_reduction.type,'far_field');assert.equal(audio.input.turn_detection.threshold,.75);assert.equal(audio.input.turn_detection.silence_duration_ms,600);assert.equal(audio.input.turn_detection.interrupt_response,true);socket.close();});

test('Natural identity replies work without the word yes for the matching recipient',()=>{const f=fixture();f.payload.first_name='Doug';for(const reply of ['This is Doug speaking.','Doug speaking.','It’s Doug.','I’m Doug.','Speaking.','Yeah.','Yup.','That’s me.','This is he.'])assert.equal(f.api.nextGuidedTurn('identity',reply,f.payload).stage,'amount',reply);assert.equal(f.api.nextGuidedTurn('identity','This is Carol speaking.',f.payload).stage,'identity');});
test('Agreeing to look is distinct from finding the email',()=>{const f=fixture();for(const reply of ['Yes, I’ll take a look.','Yeah, let me check.','Okay, I am looking.','Hold on a second.','I’ll see if I can find it.']){const t=f.api.nextGuidedTurn('email',reply,f.payload);assert.equal(t.stage,'email_search',reply);assert.match(t.scriptLine,/I’ll wait/);assert.doesNotMatch(t.scriptLine,/Based on your form|sign in/);}for(const reply of ['Oh, okay, I found it.','I got it.','I see it.','I have it.','I see the email.','There it is.'])assert.equal(f.api.nextGuidedTurn('email_search',reply,f.payload).stage,'needs',reply);for(const reply of ['I can’t find it.','I don’t see it.'])assert.equal(f.api.nextGuidedTurn('email_search',reply,f.payload).stage,'access_help',reply);assert.equal(f.api.nextGuidedTurn('email_search','Yes.',f.payload).stage,'email_search');});
async function waitingForEmail(){const clock=[],f=fixture({emailClock:clock});f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await liveSession(f);session.c.payload.rehearsal_recording=true;await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});for(const [id,transcript]of [['identity','Yes.'],['amount','Yes.'],['looking','Yes, I’ll take a look.']]){await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:id,transcript});await event(session.ai,{type:'response.done',response:{status:'completed'}});}const mark=session.socket.sent.filter(e=>e.event==='mark'&&e.mark.name.startsWith('manager-email-search-')).at(-1);return {f,clock,session,mark};}
test('Five-second email help offer waits for playback and runs only once',async()=>{const {clock,session,mark}=await waitingForEmail();try{assert.ok(mark);assert.equal(clock.length,0);await event(session.socket,{event:'mark',mark:mark.mark});assert.equal(clock.length,1);assert.equal(clock[0].ms,5000);clock[0].fn();let req=session.ai.sent.filter(e=>e.type==='response.create').at(-1).response;assert.match(req.instructions,/send you a new welcome email/);assert.doesNotMatch(req.instructions,/email has been sent/);await event(session.ai,{type:'response.done',response:{status:'completed'}});const before=session.ai.sent.filter(e=>e.type==='response.create').length;clock[0].fn();assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,before);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'found-after-offer',transcript:'Oh, I found it.'});req=session.ai.sent.filter(e=>e.type==='response.create').at(-1).response;assert.match(req.instructions,/Based on your form/);}finally{session.socket.close();}});
test('Speech, found email and disconnect cancel stale waiting prompts',async()=>{for(const reason of ['speech','found','close']){const {clock,session,mark}=await waitingForEmail();try{await event(session.socket,{event:'mark',mark:mark.mark});if(reason==='speech')await event(session.ai,{type:'input_audio_buffer.speech_started'});if(reason==='found')await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'found',transcript:'I found it.'});if(reason==='pause')await event(session.socket,{event:'test_pause'});if(reason==='close')session.socket.close();if(reason!=='pause')assert.equal(clock[0].cancelled,true,reason);const before=session.ai.sent.filter(e=>e.type==='response.create').length;if(reason!=='pause')clock[0].fn();assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,before,reason);}finally{session.socket.close();}}});

async function requestedWelcome(f){const session=await liveSession(f);await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});for(const[item_id,transcript]of [['identity','Yes.'],['amount','Yes.'],['missing','I can’t find the email.'],['resend','Yes, please.']]){await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id,transcript});await event(session.ai,{type:'response.done',response:{status:'completed'}});}return session;}
test('Client accepted resend invokes original welcome service for immutable call recipient',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await requestedWelcome(f);try{assert.equal(f.counts.emails,1);assert.deepEqual(f.counts.lastFetch.body,{action:'send_login',template:'welcome',caller_action_id:f.payload.action_id,lead_id:f.payload.lead_id});assert.equal(session.c.result.welcome_email_resend.provider_accepted,true);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/sent a new welcome email/);}finally{session.socket.close();}});
test('Failed welcome service never produces a sent-email acknowledgment',async()=>{const f=fixture({mailAccepted:false});f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await requestedWelcome(f);try{assert.equal(f.counts.emails,1);assert.equal(session.c.result.welcome_email_resend.provider_accepted,false);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/couldn’t confirm/);}finally{session.socket.close();}});
test('Declining or continuing to search does not authorize a welcome resend',()=>{const f=fixture();for(const words of ['No.','Yes, but do not send it.','No need, thanks.','Yes, I’ll take a look.'])assert.notEqual(f.api.nextGuidedTurn('access_help',words,f.payload).resendWelcome,true,words);for(const words of ['Yes.','Yup.','Please do.','That would help.','Go ahead.'])assert.equal(f.api.nextGuidedTurn('access_help',words,f.payload).resendWelcome,true,words);});

async function proposedCallback(f,{rehearsal=false}={}){f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await liveSession(f);session.c.payload.rehearsal_recording=rehearsal;await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});for(const[item_id,transcript]of [['identity','Yes.'],['callback-request','Can you call me back?'],['callback-time','Tomorrow at noon Eastern.']]){await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id,transcript});await event(session.ai,{type:'response.done',response:{status:'completed'}});}const date=new Date(Date.now()+86400000);date.setUTCHours(16,0,0,0);await event(session.ai,{type:'response.function_call_arguments.done',call_id:'callback-proposal',name:'propose_callback',arguments:JSON.stringify({callback_at:date.toISOString(),timezone:'America/New_York',client_quote:'Tomorrow at noon Eastern.'})});await event(session.ai,{type:'response.done',response:{status:'completed'}});return session;}
test('Callback reads exact time before saving and only a clear confirmation creates the CRM job',async()=>{const f=fixture(),session=await proposedCallback(f);try{assert.equal(f.counts.schedules,undefined);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/I can call you on/);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'callback-confirm',transcript:'Yes, that works.'});assert.equal(f.counts.schedules,1);assert.equal(session.c.result.callback_schedule.scheduled,true);assert.equal(f.counts.lastFetch.body.action_id,f.payload.action_id);assert.equal(f.counts.lastFetch.body.confirmation_quote,'Yes, that works.');assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/You’re scheduled for/);}finally{session.socket.close();}});
test('Failed callback save never produces a scheduled acknowledgment',async()=>{const f=fixture({callbackSaved:false}),session=await proposedCallback(f);try{await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'callback-confirm',transcript:'Yes.'});assert.equal(f.counts.schedules,1);assert.equal(session.c.result.callback_schedule,undefined);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/couldn’t confirm/);}finally{session.socket.close();}});
test('Rehearsal callback is simulated without contacting the CRM scheduler',async()=>{const f=fixture(),session=await proposedCallback(f,{rehearsal:true});try{await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'callback-confirm',transcript:'That works.'});assert.equal(f.counts.schedules,undefined);assert.equal(session.c.result.callback_schedule.simulated,true);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/callback is simulated/);}finally{session.socket.close();}});
test('Direct-number call accepts an explicit international number and uses approved opening without PrepHub substitution',async()=>{const f=fixture();Object.assign(f.payload,{lead_id:null,first_name:'',phone:'+573001234567',direct_number:true,call_mode:'direct_number',owner_authorized:true,caller_settings:{version:10,settings:{script_delivery:'verbatim'}},script:{objective:'Owner custom call',opening:'Hello, this is Daisy with DPA Help Center. Is now a good time?',key_points:['Deliver the owner message'],script_text:'Hello, this is Daisy with DPA Help Center. Is now a good time?\n[Wait.]\nYour requested resource is ready.',recording_requested:true}});assert.equal(f.api.validRequest(f.payload),true);assert.match(f.api.callInstructions(f.payload),/approved script below is the authority/);assert.doesNotMatch(f.api.callInstructions(f.payload),/Based on your form|welcome email from/);const res=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},res);assert.equal(res.statusCode,200);const {socket,ai}=await liveSession(f);await ai.emitAsync('message',JSON.stringify({type:'session.updated'}));assert.equal(f.counts.lastDial,'+573001234567');const first=ai.sent.find(e=>e.type==='response.create');assert.ok(first.response.instructions.includes(f.payload.script.opening));assert.ok(!first.response.instructions.includes('who contacted DPA'));socket.emit('close');});
test('Direct-number requests reject guided mode and missing owner authorization',()=>{const f=fixture();Object.assign(f.payload,{phone:'+15555550101',direct_number:true,call_mode:'direct_number',owner_authorized:true,caller_settings:{version:10,settings:{script_delivery:'guided'}}});assert.equal(f.api.validRequest(f.payload),false);f.payload.caller_settings.settings.script_delivery='verbatim';assert.equal(f.api.validRequest(f.payload),true);f.payload.owner_authorized=false;assert.equal(f.api.validRequest(f.payload),false);});
test('Owner-managed recording does not insert the notice and captures without falsely logging client consent',async()=>{const f=fixture();f.payload.direct_number=true;f.payload.call_mode='direct_number';f.payload.owner_authorized=true;f.payload.phone='+15555550101';f.payload.caller_settings={version:11,settings:{recording_mode:'owner_managed',script_delivery:'verbatim'}};f.payload.script.script_text='Hello. Your requested resource is ready.';f.payload.script.opening='Hello, this is Daisy with DPA Help Center. Is now a good time?';const prompt=f.api.callInstructions(f.payload);assert.doesNotMatch(prompt,/This call may be recorded|By continuing, you agree|May I record this call/);const session=await liveSession(f);try{await new Promise(resolve=>setImmediate(resolve));assert.equal(f.counts.recordings,1);assert.equal(session.c.result.recording_consent,undefined);assert.equal(session.c.result.recording_authorized,true);assert.equal(session.c.result.recording_authorization_source,'owner_managed_configuration');await session.ai.emitAsync('message',JSON.stringify({type:'conversation.item.input_audio_transcription.completed',item_id:'recording-objection',transcript:'Please stop recording this call.'}));assert.equal(f.counts.stops,1);assert.equal(session.c.result.recording_declined,true);}finally{session.socket.close();}});
test('Owner-managed guided preparation skips the injected recording line',()=>{const f=fixture();f.payload.caller_settings={version:11,settings:{recording_mode:'owner_managed',script_delivery:'guided'}};const turn=f.api.nextGuidedTurn('identity','This is Test speaking',f.payload);assert.doesNotMatch(turn.scriptLine,/record|By continuing/i);assert.doesNotMatch(f.api.callInstructions(f.payload),/This call may be recorded|By continuing, you agree/);});
test('Live call snapshot returns persisted transcript without provider reconciliation or AI',async()=>{const f=fixture();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},f.response());const record=f.records.get(f.payload.action_id);record.transcript=[{role:'client',text:'I have a question.'}];const before={...f.counts},r=f.response();r.set=()=>r;await f.routes.get('GET /api/v1/manager/calls/:id/live')({params:{id:f.payload.action_id}},r);assert.equal(r.body.transcript[0].text,'I have a question.');assert.equal(f.counts.callbacks,before.callbacks);assert.equal(f.counts.calls,before.calls);});

test('International direct-number calls dispatch without a CRM client',async()=>{const f=fixture();Object.assign(f.payload,{lead_id:null,direct_number:true,call_mode:'direct_number',owner_authorized:true,phone:'+573001234567',caller_settings:{version:11,settings:{script_delivery:'verbatim',recording_mode:'owner_managed'}}});delete f.payload.permission_verified;const r=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},r);assert.equal(r.statusCode,200);assert.equal(f.counts.lastDial,'+573001234567');assert.equal(f.counts.calls,1);});
test('Provider destination rejection is saved and returned without leaking the original error',async()=>{const f=fixture({dispatchError:Object.assign(Error('private provider details'),{code:21215,status:403})});const r=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},r);assert.equal(r.statusCode,502);assert.equal(r.body.provider_error_code,21215);assert.match(r.body.error,/geographic permissions/);assert.equal(r.body.dispatch_rejected,true);assert.equal(f.records.get(f.payload.action_id).status,'failed');assert.ok(!JSON.stringify(r.body).includes('private provider details'));});
test('Unknown dispatch errors remain unconfirmed and are never labeled rejected',async()=>{const f=fixture({dispatchError:Error('network timeout')});const r=f.response();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},r);assert.equal(r.body.dispatch_rejected,false);assert.equal(f.records.get(f.payload.action_id).status,'unconfirmed');});

test('Owner can stop an active direct-number call and repeated stop does not redial',async()=>{const f=fixture();await f.routes.get('POST /api/v1/manager/calls')({body:f.payload},f.response());f.records.get(f.payload.action_id).status='in-progress';const r=f.response();await f.routes.get('POST /api/v1/manager/calls/:id/stop')({params:{id:f.payload.action_id}},r);assert.equal(r.statusCode,200);assert.equal(r.body.status,'completed');assert.equal(f.counts.hangups,1);assert.equal(f.counts.calls,1);});
test('Missing provider identity never produces a false hang-up confirmation',async()=>{const f=fixture(),r=f.response();f.records.set(f.payload.action_id,{...f.payload,status:'unconfirmed',result:{}});await f.routes.get('POST /api/v1/manager/calls/:id/stop')({params:{id:f.payload.action_id}},r);assert.equal(r.statusCode,409);assert.equal(f.records.get(f.payload.action_id).status,'unconfirmed');});
test('live monitor forwards customer and Daisy audio, without listener hang-up control',async()=>{const f=fixture();f.payload.requested_by='owner';const {c,socket,ai}=await liveSession(f),r=f.response();r.set=()=>r;await f.routes.get('POST /api/v1/manager/calls/:id/listen')({params:{id:c.action_id},body:{owner_id:'owner'}},r);assert.equal(r.statusCode,200);const listener=new FakeSocket();f.service.handleUpgrade({url:'/api/v1/manager/listen',headers:{origin:'https://www.dpahelpcenter.com'}},listener,null);await event(listener,{event:'authorize',action_id:c.action_id,token:r.body.token});await event(socket,{event:'media',media:{payload:'/w=='}});await event(ai,{type:'response.output_audio.delta',delta:'/w=='});assert.ok(listener.sent.some(e=>e.event==='media'&&e.track==='client'));assert.ok(listener.sent.some(e=>e.event==='media'&&e.track==='daisy'));listener.close();assert.equal(socket.readyState,1);assert.equal(f.counts.hangups,undefined);socket.close();});
test('congratulations delivery splits the greeting from the concerned follow-up without laughter',()=>{const f=fixture();f.payload.first_name='Taylor';f.payload.caller_settings={version:1,settings:{script_delivery:'guided'}};f.payload.script.script_text='[PrepHub:identity]\nHi, {first_name}. Congratulations!\n\n[PrepHub:identity_followup]\nI’m sorry. I should have asked—is this {first_name} speaking?\n\n[PrepHub:amount]\nWhat amount were you looking for?';assert.equal(f.api.timedOpening(f.payload),true);assert.match(f.api.openingDelivery(f.api.simpleLine('identity',f.payload),f.payload),/then STOP speaking/);assert.match(f.api.openingDelivery(f.api.simpleLine('identity_followup',f.payload),f.payload),/slightly concerned/);assert.equal(f.api.openingDelivery('Other words',f.payload),'');});
test('confusion about congratulations gets the approved explanation without an immediate identity question',()=>{const f=fixture();openingFixture(f);for(const stage of ['opening_wait','identity'])for(const words of ['Congratulations.','Congratulations?','Congratulations for what?','What?','Huh?','What do you mean?','What is this about?','Yes, congratulations for what?']){const turn=f.api.nextGuidedTurn(stage,words,f.payload);assert.equal(turn.stage,'opening_explained');assert.match(turn.scriptLine,/I see you were looking for around \$35,000/);assert.match(turn.scriptLine,/Is that correct\?/);assert.doesNotMatch(turn.scriptLine,/sorry|is this Taylor|approved|awarded|qualified/);}assert.equal(f.api.nextGuidedTurn('identity','Stop calling me',f.payload).stage,'wrapup');});
test('acknowledging the explanation does not independently confirm identity',()=>{const f=fixture();openingFixture(f);assert.equal(f.api.nextGuidedTurn('opening_explained','Yes',f.payload).stage,'identity_after_amount');assert.equal(f.api.nextGuidedTurn('opening_explained','This is Taylor',f.payload).stage,'amount');assert.equal(f.api.nextGuidedTurn('opening_explained','Stop calling me',f.payload).stage,'wrapup');});

function openingFixture(f){f.payload.first_name='Taylor';f.payload.caller_settings={version:1,settings:{script_delivery:'guided'}};f.payload.script.script_text='[PrepHub:identity]\nHi, {first_name}. Congratulations!\n\n[PrepHub:identity_followup]\nI’m sorry. I should have asked—is this {first_name} speaking?\n\n[PrepHub:amount]\nWhat amount were you looking for?';}
async function finishOpening(session){await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.output_audio_transcript.done',transcript:'Hi, Taylor. Congratulations!'});await event(session.ai,{type:'response.done',response:{status:'completed'}});}
test('one-and-a-half-second response window begins after greeting playback and sends the follow-up only once',async()=>{const clock=[],f=fixture({emailClock:clock});openingFixture(f);const session=await liveSession(f);await finishOpening(session);assert.equal(clock.length,0);const mark=session.socket.sent.find(e=>e.event==='mark'&&e.mark.name==='manager-opening-0');assert.ok(mark);await event(session.socket,{event:'mark',mark:mark.mark});assert.equal(clock.length,1);assert.equal(clock[0].ms,1500);await clock[0].fn();const responses=session.ai.sent.filter(e=>e.type==='response.create');assert.equal(responses.length,2);assert.match(responses[1].response.instructions,/I’m sorry. I should have asked—is this Taylor speaking/);await clock[0].fn();assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,2);session.socket.close();});
test('speech during the response window cancels automatic follow-up and answers the actual question',async()=>{const clock=[],f=fixture({emailClock:clock});openingFixture(f);const session=await liveSession(f);await finishOpening(session);const mark=session.socket.sent.find(e=>e.event==='mark'&&e.mark.name==='manager-opening-0');await event(session.socket,{event:'mark',mark:mark.mark});await event(session.ai,{type:'input_audio_buffer.speech_started'});assert.equal(clock[0].cancelled,true);await clock[0].fn();assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,1);await event(session.ai,{type:'input_audio_buffer.speech_stopped'});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'question',transcript:'Congratulations for what?'});const last=session.ai.sent.filter(e=>e.type==='response.create').at(-1);assert.match(last.response.instructions,/I see you were looking for around \$35,000 in down payment assistance/);assert.doesNotMatch(last.response.instructions,/What amount were you looking for/);session.socket.close();});
test('closing cancels pending opening follow-up; yes to congratulations alone is not identity',async()=>{const clock=[],f=fixture({emailClock:clock});openingFixture(f);const session=await liveSession(f);await finishOpening(session);const mark=session.socket.sent.find(e=>e.event==='mark'&&e.mark.name==='manager-opening-0');await event(session.socket,{event:'mark',mark:mark.mark});session.socket.close();assert.equal(clock[0].cancelled,true);await clock[0].fn();assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,1);const turn=f.api.nextGuidedTurn('opening_wait','Yes',f.payload);assert.equal(turn.stage,'identity');assert.match(turn.scriptLine,/I should have asked/);});
test('owner can run a saved guided script to an international phone without a CRM record',async()=>{const f=fixture();Object.assign(f.payload,{lead_id:null,call_mode:'saved_script_phone',owner_authorized:true,phone:'+573001234567',first_name:'',caller_settings:{version:12,settings:{script_delivery:'guided',recording_mode:'owner_managed'}}});assert.equal(f.api.validRequest(f.payload),true);delete f.payload.owner_authorized;delete f.payload.permission_verified;assert.equal(f.api.validRequest(f.payload),false);});

test('a recognized requested amount is used instead of the generic 35000 introduction',()=>{const f=fixture();f.payload.preparation_context.intake.estimated_dpa=22000;for(const stage of ['amount','opening_explanation']){const words=f.api.simpleLine(stage,f.payload);assert.match(words,/\$22,000/);assert.doesNotMatch(words,/\$35,000|Doug told/);assert.match(words,/is that correct/i);}});
test('an unlinked phone gets the Doug introduction without inventing an amount, email or account',()=>{const f=fixture();f.payload.lead_id=null;f.payload.preparation_context={intake:{}};for(const stage of ['amount','opening_explanation']){const words=f.api.simpleLine(stage,f.payload);assert.match(words,/Doug told me to give you a call/);assert.match(words,/up to \$35,000/);assert.ok(!words.includes('?'));}const next=f.api.nextGuidedTurn('amount','Tell me more',f.payload);assert.equal(next.stage,'prospect_next');assert.doesNotMatch(next.scriptLine,/received a welcome email|based on your form/);assert.equal(f.api.nextGuidedTurn('amount','No, I’m not interested',f.payload).stage,'wrapup');});
test('confirming amount during the explanation avoids repeating it after identity confirmation',()=>{const f=fixture();openingFixture(f);const accepted=f.api.nextGuidedTurn('opening_explained','Yes',f.payload);assert.equal(accepted.stage,'identity_after_amount');assert.equal(f.api.nextGuidedTurn(accepted.stage,'This is Taylor',f.payload).stage,'email');});

test('natural identity claims work during the greeting and identity question, including Doug for Douglas',()=>{const f=fixture();openingFixture(f);f.payload.first_name='Douglas';for(const stage of ['opening_wait','identity','identity_after_amount'])for(const words of ['This is Doug speaking.','This is Douglas speaking.','This is him.','This is her.']){const t=f.api.nextGuidedTurn(stage,words,f.payload);assert.ok(['amount','email'].includes(t.stage),stage+' '+words);}for(const words of ['Yes.','Yeah.','Speaking.'])assert.equal(f.api.nextGuidedTurn('identity',words,f.payload).stage,'amount');assert.equal(f.api.nextGuidedTurn('identity','This is David speaking.',f.payload).stage,'identity');});

test('relative callback asks only timezone, then saves without a second yes or date readback',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await liveSession(f);try{await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'relative-request',transcript:'Call me back in fifteen minutes.'});assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/What time zone/);assert.equal(f.counts.schedules,undefined);await event(session.ai,{type:'response.done',response:{status:'completed'}});await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'zone',transcript:'Eastern time.'});assert.equal(f.counts.schedules,1);assert.equal(f.counts.lastFetch.body.relative_seconds,900);assert.equal(f.counts.lastFetch.body.confirmation_quote,'Eastern time.');assert.equal(session.c.result.callback_schedule.scheduled,true);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/call you back in 15 minutes/);}finally{session.socket.close();}});

test('unknown timezone gets a city question and a known city resolves it without more time questions',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await liveSession(f);try{await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});for(const [id,words] of [['request','Call me back in a couple minutes.'],['unknown',"I don't know my time zone."]]){await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:id,transcript:words});await event(session.ai,{type:'response.done',response:{status:'completed'}});}assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/city and state/);await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'city',transcript:'Miami, Florida.'});assert.equal(f.counts.schedules,1);assert.equal(f.counts.lastFetch.body.relative_seconds,120);assert.equal(f.counts.lastFetch.body.timezone,'America/New_York');}finally{session.socket.close();}});


test('short natural affirmative replies advance identity and yes/no preparation steps',()=>{const f=fixture();for(const answer of ['Yes.','Yeah.','Uh-huh.','Uh huh.','Mhm.','Mm-hmm.']){assert.equal(f.api.nextGuidedTurn('identity',answer,f.payload).stage,'amount',answer);assert.equal(f.api.nextGuidedTurn('amount',answer,f.payload).stage,'email',answer);assert.equal(f.api.nextGuidedTurn('orientation',answer,f.payload).stage,'login',answer);}assert.equal(f.api.nextGuidedTurn('identity','Uh-uh.',f.payload).stage,'identity');});
test('explicit non-speech transcription markers do not become client replies or trigger another response',async()=>{const f=fixture();f.payload.caller_settings={version:10,settings:{script_delivery:'guided'}};const session=await liveSession(f);try{await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});const before=session.ai.sent.filter(e=>e.type==='response.create').length;for(const text of ['[background noise]','[music]','(inaudible)'])await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:text,transcript:text});assert.equal(session.ai.sent.filter(e=>e.type==='response.create').length,before);assert.equal(session.c.transcript.filter(t=>t.role==='client').length,0);}finally{session.socket.close();}});

function proactiveEmailFixture(f){f.payload.caller_settings={version:12,settings:{script_delivery:'guided'}};f.payload.script.script_text='[PrepHub:identity]\nHi, {first_name}. Congratulations on your first-time homebuyer down payment assistance request!\n\n[PrepHub:identity_followup]\nOh, I’m sorry. Is this {first_name} speaking?\n\n[PrepHub:amount]\nWere you looking for {assistance_amount}?\n\n[PrepHub:email]\nYou may have already received your PrepHub welcome email, but I’m going to send you a fresh one now so it’s right at the top of your inbox.\n\n[PrepHub:email_sent]\nOkay, I’ve sent it. Look for the PrepHub email and let me know when you see it.';}
async function autoEmailAnnouncement(f){proactiveEmailFixture(f);const session=await liveSession(f);await event(session.ai,{type:'session.updated'});await event(session.ai,{type:'response.done',response:{status:'completed'}});for(const [id,text]of [['name','This is Test speaking.'],['amount','Yes.']]){await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:id,transcript:text});await event(session.ai,{type:'response.done',response:{status:'completed'}});}return session;}
test('new longer congratulations opening retains the timed pause and new identity follow-up',()=>{const f=fixture();proactiveEmailFixture(f);assert.equal(f.api.timedOpening(f.payload),true);assert.match(f.api.openingDelivery(f.api.simpleLine('identity',f.payload),f.payload),/STOP speaking/);assert.equal(f.api.nextGuidedTurn('opening_wait','Yes',f.payload).scriptLine,'Oh, I’m sorry. Is this Test speaking?');});
test('proactive email sends after announcement playback without another permission or customer turn',async()=>{const f=fixture(),session=await autoEmailAnnouncement(f);try{assert.equal(f.counts.emails,undefined);const mark=session.socket.sent.find(e=>e.event==='mark'&&e.mark.name.startsWith('manager-auto-email-'));assert.ok(mark);await event(session.socket,{event:'mark',mark:mark.mark});assert.equal(f.counts.emails,1);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/Okay, I’ve sent it/);await event(session.socket,{event:'mark',mark:mark.mark});assert.equal(f.counts.emails,1);}finally{session.socket.close();}});
test('a failed proactive send never claims the email was sent',async()=>{const f=fixture({mailAccepted:false}),session=await autoEmailAnnouncement(f);try{const mark=session.socket.sent.find(e=>e.event==='mark'&&e.mark.name.startsWith('manager-auto-email-'));await event(session.socket,{event:'mark',mark:mark.mark});assert.equal(f.counts.emails,1);assert.match(session.ai.sent.filter(e=>e.type==='response.create').at(-1).response.instructions,/couldn’t confirm the email was sent/);assert.equal(session.c.result.welcome_email_resend.provider_accepted,false);}finally{session.socket.close();}});
test('a callback request cancels an unplayed automatic-email marker',async()=>{const f=fixture(),session=await autoEmailAnnouncement(f);try{const mark=session.socket.sent.find(e=>e.event==='mark'&&e.mark.name.startsWith('manager-auto-email-'));await event(session.ai,{type:'conversation.item.input_audio_transcription.completed',item_id:'callback',transcript:'Call me back in two minutes.'});await event(session.socket,{event:'mark',mark:mark.mark});assert.equal(f.counts.emails,undefined);}finally{session.socket.close();}});
